   118|export async function handleIVXAutonomyCloudFrontInvalidateRequest(request: Request): Promise<Response> {
   119|  try {
   120|    await assertIVXOwnerOnly(request);
   121|    const body = readObjectInput(await request.json().catch(() => ({})));
   122|    const paths = readStringArray(body.paths);
   123|    const apply = body.apply === true;
   124|    const callerReference = typeof body.callerReference === 'string' ? body.callerReference : undefined;
   125|    const distributionId = typeof body.distributionId === 'string' && body.distributionId.trim().length > 0
   126|      ? body.distributionId.trim()
   127|      : undefined;
   128|
   129|    if (paths.length === 0) {
   130|      return ownerOnlyJson({
   131|        ok: false,
   132|        marker: IVX_AUTONOMY_MARKER,
   133|        error: 'paths[] is required.',
   134|      }, 400);
   135|    }
   136|
   137|    if (!apply) {
   138|      return ownerOnlyJson({
   139|        ok: true,
   140|        marker: IVX_AUTONOMY_MARKER,
   141|        mode: 'dry_run',
   142|        wouldInvalidate: {
